import { DigoAsset } from '@digo-org/digo-api';
import { ResponsiveContainer, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend } from 'recharts';

const YEAR_COLORS = ['#3b82f6', '#8b5cf6', '#ec4899', '#f59e0b', '#10b981'];

export class Asset extends DigoAsset {
  constructor() {
    super();
  }

  override render() {
    // Transform data: each quarter (row) becomes a data point with all year values
    const chartData = this.instances?.map((instance) => {
      const dataPoint: any = { name: instance['quarter-label'] as string };

      // For each year in timeArray, add its value
      this.timeArray?.forEach((year, yearIndex) => {
        const revenueArray = instance['quarter-values'] as number[];
        dataPoint[year] = revenueArray?.[yearIndex] || 0;
      });

      return dataPoint;
    }) || [];

    return (
      <div style={{
        width: '100%',
        height: '100%',
        backgroundColor: this.globalParameters['background-color'] as string || '#ffffff',
        padding: '20px',
        fontFamily: 'sans-serif',
        boxSizing: 'border-box'
      }}>
        {this.globalParameters['show-title'] && (
          <h2 style={{
            textAlign: 'center',
            margin: '0 0 20px 0',
            fontSize: '24px',
            color: '#1f2937',
            fontWeight: 'bold'
          }}>
            {this.globalParameters['chart-title'] as string || 'Multi-Year Quarterly Revenue'}
          </h2>
        )}

        <ResponsiveContainer width="100%" height="100%">
          <LineChart
            data={chartData}
            margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
          >
            {this.globalParameters['show-grid'] && (
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
            )}

            <XAxis 
              dataKey="name" 
              stroke="#6b7280"
              label={{ value: 'Quarter', position: 'insideBottom', offset: -5 }}
            />

            <YAxis 
              stroke="#6b7280"
              label={{ value: 'Revenue (USD)', angle: -90, position: 'insideLeft' }}
            />

            {this.globalParameters['show-tooltip'] && (
              <Tooltip formatter={(value: number) => `$${value.toLocaleString()}`} />
            )}

            {this.globalParameters['show-legend'] && <Legend />}

            {this.timeArray?.map((year, yearIndex) => {
              const lineColor = YEAR_COLORS[yearIndex % YEAR_COLORS.length];

              return (
                <Line
                  key={year}
                  type={this.globalParameters['smooth-curve'] ? 'monotone' : 'linear'}
                  dataKey={year}
                  stroke={lineColor}
                  strokeWidth={this.globalParameters['stroke-width'] as number || 2}
                  dot={this.globalParameters['show-dots']}
                  name={year}
                  activeDot={{ r: 8 }}
                />
              );
            })}
          </LineChart>
        </ResponsiveContainer>
      </div>
    );
  }
}

